#define MAXN 100005

int main() {
    int n;
    int p[MAXN];

    // Read input
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &p[i]);
    }

    // We'll simulate building the parentheses sequence
    // For each closing bracket position i (1-indexed), p[i] tells which opening bracket it matches
    // We need to find a valid parentheses sequence of length 2n

    // First, check if the permutation can correspond to a valid parentheses sequence
    // We'll use a stack to simulate

    int stack[MAXN];
    int top = 0;
    char result[2 * MAXN];
    int res_idx = 0;
    int current_open = 1; // next opening bracket index to place

    // We'll process closing brackets in order
    for (int i = 1; i <= n; i++) {
        int match = p[i];

        // We need to have enough opening brackets up to 'match' that are not yet matched
        // The opening brackets are numbered 1..n in order of appearance

        // First, place any needed opening brackets before this closing bracket
        while (current_open <= match) {
            stack[top++] = current_open;
            result[res_idx++] = '(';
            current_open++;
        }

        // Now the top of stack should be the matching opening bracket
        if (top == 0 || stack[top - 1] != match) {
            printf(":(\n");
            return 0;
        }

        // Pop and place closing bracket
        top--;
        result[res_idx++] = ')';
    }

    // After processing all closing brackets, we should have placed all opening brackets
    // current_open should be n+1
    if (current_open != n + 1) {
        printf(":(\n");
        return 0;
    }

    // Also the stack should be empty
    if (top != 0) {
        printf(":(\n");
        return 0;
    }

    result[res_idx] = '\0';
    printf("%s\n", result);

    return 0;
}

