        // We must place openings in increasing order of their match index
        // For each closing bracket i (1-based), we need p[i]-th opening bracket
        // So we maintain a stack of unmatched openings to place them correctly

        // Approach: simulate with stack where we push opening positions
        // and when we need to close the p[i]-th opening, we check if it's on top.

        Stack<Integer> stack = new Stack<>();
        int nextOpen = 1; // numbering of openings
        int resultPos = 0;

        for (int i = 0; i < n; i++) {
            int targetOpen = p[i];
