import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int[] p = new int[n + 1];
        for (int i = 1; i <= n; i++) p[i] = fs.nextInt();

        int[] closeAt = new int[n + 1]; // closeAt[j] = i means j-th open closes at i-th close
        for (int i = 1; i <= n; i++) {
            closeAt[p[i]] = i;
        }

        StringBuilder ans = new StringBuilder(2 * n);
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        int nextOpen = 1;

        for (int i = 1; i <= n; i++) {
            int need = p[i];

            while (nextOpen <= need) {
                stack.push(nextOpen);
                ans.append('(');
                nextOpen++;
            }

            if (stack.isEmpty() || stack.peek() != need) {
                System.out.println(":(");
                return;
            }

            stack.pop();
            ans.append(')');
        }

        if (!stack.isEmpty()) {
            System.out.println(":(");
            return;
        }

        System.out.println(ans.toString());
    }
